(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.014+t*0.4)*22+Math.cos(y*0.011-t*0.28)*16;
  const w1y = Math.cos(y*0.016-t*0.32)*22+Math.sin(x*0.013+t*0.42)*16;
  const w2x = Math.sin((x+y)*0.009+t*0.18)*12+Math.cos((x-y)*0.013-t*0.22)*9;
  const w2y = Math.cos((x-y)*0.011-t*0.24)*12+Math.sin((x+y)*0.014+t*0.2)*9;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const wells = [
    [160+Math.sin(t*0.5)*120,80+Math.cos(t*0.35)*60,20000,0.8],
    [320+Math.cos(t*0.4)*100,160+Math.sin(t*0.6)*70,14000,1.2],
    [240+Math.sin(t*0.25+2)*150,120+Math.cos(t*0.45+1)*100,25000,0.55],
    [80+Math.cos(t*0.7+1)*60,200+Math.sin(t*0.5+3)*50,9000,1.5],
    [400+Math.sin(t*0.3+4)*80,40+Math.cos(t*0.8+2)*50,16000,0.9],
    [240+Math.cos(t*0.3+5)*130,220+Math.sin(t*0.5)*60,11000,1.1],
    [50+Math.sin(t*0.6+3)*50,110+Math.cos(t*0.4+1)*80,10000,1.35],
    [430+Math.cos(t*0.45+2)*55,185+Math.sin(t*0.55+4)*40,12000,0.7]
  ];
  let pot=0,kin=0,phase=0;
  for(const[wX,wY,mass,spd]of wells){
    const dx=sx-wX,dy=sy-wY,dSq=dx*dx+dy*dy+120,d=Math.sqrt(dSq);
    const inv=mass/dSq;
    pot+=inv*28;
    const vx=-dy/dSq*mass*0.001,vy=dx/dSq*mass*0.001;
    kin+=Math.sqrt(vx*vx+vy*vy)*750;
    phase+=Math.sin(d*0.075-t*spd)*inv*0.55;
  }
  pot=Math.tanh(pot*0.14);kin=Math.tanh(kin*0.75);phase=Math.tanh(phase*2.2);
  const eRatio=pot/(pot+kin+0.008);
  const bg=(Math.sin(sx*0.032+sy*0.018+t*0.85)+Math.sin(sx*0.022-sy*0.032+t*1.25)+Math.sin((sx+sy)*0.095+t*2.7)*0.3+Math.sin((sx-sy)*0.075-t*2.1)*0.3)/2.5;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const orb=(Math.sin(dist*0.055-ang*4-t*1.7)+Math.sin(dist*0.04+ang*5-t*1.3)+Math.sin(dist*0.075-ang*2+t*0.65))*0.33;
  const cell=Math.sin(sx*0.11)*Math.sin(sy*0.11)+Math.sin((sx*0.7+sy*0.3)*0.09+t*0.45)*0.4+Math.sin((sx*0.3+sy*0.7)*0.09-t*0.35)*0.4;
  const act=phase*0.55+pot*0.45;
  const inh=kin*0.5+bg*0.3+Math.abs(orb)*0.2;
  const rxn=Math.tanh((act-inh*0.62+orb*0.38+cell*0.12)*2.6);
  const conv=1-Math.abs(eRatio-0.5)*2;
  const glow=conv*conv*(0.4+Math.abs(rxn)*0.6);
  const v=rxn*0.55+glow*0.35+0.1;
  const cl=Math.max(0,Math.min(1,v));
  const pal=[[1,1,10],[4,8,35],[8,50,110],[0,210,255],[160,0,255],[255,50,170],[255,215,0],[255,255,235]];
  const shift=eRatio*0.35;
  const sIdx=Math.max(0,Math.min(pal.length-1,cl*(pal.length-1)+(shift-0.17)*2.5));
  const si=Math.min(sIdx|0,pal.length-2),sf=sIdx-si;
  const eGlow=Math.abs(rxn)>0.55?1.35:1.0;
  const nBoost=glow>0.45?1.25+glow*0.35:1.0;
  const lum=eGlow*nBoost;
  return[
    Math.min(255,(pal[si][0]+(pal[si+1][0]-pal[si][0])*sf)*lum)|0,
    Math.min(255,(pal[si][1]+(pal[si+1][1]-pal[si][1])*sf)*lum)|0,
    Math.min(255,(pal[si][2]+(pal[si+1][2]-pal[si][2])*sf)*lum)|0
  ];
}
